// Records every request the app routes through HTTPS_PROXY / HTTP_PROXY and
// refuses it, so nothing leaves the machine. One line per request:
// <ISO time> CONNECT host:port   or   <ISO time> GET http://host/path
import http from 'node:http';
import fs from 'node:fs';

const [port, out] = process.argv.slice(2);
const log = (line) => fs.appendFileSync(out, `${new Date().toISOString()} ${line}\n`);

const server = http.createServer((req, res) => {
  log(`${req.method} ${req.url}`);
  res.writeHead(502).end();
});
server.on('connect', (req, socket) => {
  log(`CONNECT ${req.url}`);
  socket.end('HTTP/1.1 502 Bad Gateway\r\n\r\n');
});
server.listen(Number(port), '127.0.0.1', () => log(`listening ${port}`));

