// Turns a copied data folder's conf into the README's fake-printer setup:
// jusprin.fake_printer on, the A1 mini model installed and its system preset
// selected. The checksum line is dropped (the app logs a harmless-edit note).
import fs from 'node:fs';
const [file] = process.argv.slice(2);
const text = fs.readFileSync(file, 'utf8').replace(/\n# MD5 checksum [0-9A-F]+\s*$/, '\n');
const conf = JSON.parse(text);
conf.jusprin = { ...(conf.jusprin ?? {}), fake_printer: true };
conf.models.push({ model: 'Bambu Lab A1 mini', nozzle_diameter: '0.4', vendor: 'BBL' });
conf.presets.machine = 'Bambu Lab A1 mini 0.4 nozzle';
fs.writeFileSync(file, JSON.stringify(conf, null, '\t') + '\n');

